QString unicodeName(char32_t codePoint) {
  auto it = std::lower_bound(std::begin(ENTRIES), std::end(ENTRIES), codePoint,
                             [](const Entry &e, char32_t cp) { return e.codePoint < cp; });
  if ((it != std::end(ENTRIES)) && (it->codePoint == codePoint)) return QString(it->name);
  if ((codePoint >= 0xE000) && (codePoint <= 0xF8FF)) return QString("Private use");
  return QString();
}
